        return Sql.unchecked(() -> {
            try (PreparedStatement ps = c.prepareStatement("SELECT * FROM messages ORDER BY id");
                 ResultSet rs = ps.executeQuery()) {
                List<Message> result = new ArrayList<>();
                while (rs.next()) {
